// Match the phone pager's CSS without triggering a layout measurement. Shared
// by scheduled polls and store-driven reads so both respect hidden pages.
export function isComponentOffPage(owner) {
  if (!owner || typeof owner.closest !== 'function' || typeof document === 'undefined') return false;
  const body = document.body;
  const page = body?.dataset?.mobilePage;
  if (!page || !body.classList?.contains('layout-basic')) return false;
  if (typeof matchMedia !== 'function' || !matchMedia('(max-width: 768px)').matches) return false;
  for (let host = owner.closest('[data-mpage]'); host; host = host.parentElement?.closest('[data-mpage]')) {
    if (!String(host.getAttribute('data-mpage') || '').split(/\s+/).includes(page)) return true;
  }
  return false;
}
